from pathlib import Path
import difflib, hashlib, sys

root = Path(\"/tmp/chg57-r19-control\")
base = root / \"base\"
target = root / \"target\"

files = [
    \"frontend/tests/helpers/sysgrid.ts\",
    \"frontend/tests/assets-vendors-bulk-preview.spec.ts\",
    \"frontend/tests/assets-workflows.spec.ts\",
]

def replace_once(text, old, new, label):
    count = text.count(old)
    if count "'!= 1:
        raise SystemExit(f"{label}: expected one occurrence, found {count}")
    return text.replace(old, new, 1)

p = files[0]
text = (base / p).read_text()
old = """export async function selectWorkspaceLogicalRow(row: LogicalGridRow) {
  const fragments = workspaceLogicalRowFragments(row)
  const wrapperCandidates = fragments.map((fragment) => fragment.locator('"'.ag-selection-checkbox'))
  const counts = await Promise.all(wrapperCandidates.map((wrapper) => wrapper.count()))
  const total = counts.reduce((sum, count) => sum + count, 0)

  if (total "'!== 1) {
    throw new Error('"\\"'`Expected exactly one row-selection checkbox wrapper for logical row '"\\"'${row.rowKey}; found '"\\"'${total}.'"\\"'`)
  }

  const wrapper = wrapperCandidates[counts.findIndex((count) => count === 1)]
  const checkbox = wrapper.getByRole('"'checkbox', { name: /Press Space to toggle row selection/ })
  await expect(wrapper).toBeVisible()
  await expect(checkbox).toHaveCount(1)
  await expect(checkbox).toBeEnabled()
  await expect(checkbox).not.toBeChecked()
  await wrapper.click()
  await expect(checkbox).toBeChecked()
  await expectWorkspaceLogicalRowSelected(row)
}\"\"\"
new = \"\"\"export async function selectWorkspaceLogicalRow(
  row: LogicalGridRow,
  { additive = false }: { additive?: boolean } = {},
) {
  const nameCell = await row.cell('name')
  await expect(nameCell).toBeVisible()

  if (additive) {
    const multiSelectModifier = process.platform === 'darwin' ? 'Meta' : 'Control'
    await nameCell.click({ modifiers: [multiSelectModifier] })
  } else {
    await nameCell.click()
  }

  await expectWorkspaceLogicalRowSelected(row)
}\"\"\"
text = replace_once(text, old, new, \"logical row selection helper\")
(target / p).write_text(text)

p = files[1]
text = (base / p).read_text()
text = replace_once(
    text,
    \"import { clickResilientButton, getWorkspaceLogicalRowByText, resetBrowserState, selectWorkspaceLogicalRow } from './helpers/sysgrid'\",
    \"import { clickResilientButton, expectWorkspaceLogicalRowSelected, getWorkspaceLogicalRowByText, resetBrowserState, selectWorkspaceLogicalRow } from './helpers/sysgrid'\",
    \"bulk preview helper import\",
)
text = replace_once(
    text,
    \"\"\"async function selectRowsByNames(page: Page, workspace: 'assets' | 'vendors', names: string[]) {
  for (const name of names) {
    const row = await getWorkspaceLogicalRowByText(page, workspace, name)
    await expect(await row.cell('name')).toHaveText(name)
    await selectWorkspaceLogicalRow(row)
  }
}\"\"\",
    \"\"\"async function selectRowsByNames(page: Page, workspace: 'assets' | 'vendors', names: string[]) {
  for (const [index, name] of names.entries()) {
    const row = await getWorkspaceLogicalRowByText(page, workspace, name)
    const nameCell = await row.cell('name')
    await expect(nameCell).toHaveText(name)
    await selectWorkspaceLogicalRow(row, { additive: index > 0 })
    await expectWorkspaceLogicalRowSelected(row)
  }
}\"\"\",
    \"bulk preview row selection loop\",
)
(target / p).write_text(text)

p = files[2]
text = (base / p).read_text()
text = replace_once(text, \"await selectWorkspaceLogicalRow(primaryCompareRow)\", \"await selectWorkspaceLogicalRow(primaryCompareRow, { additive: false })\", \"primary compare selection\")
text = replace_once(text, \"await selectWorkspaceLogicalRow(secondaryCompareRow)\", \"await selectWorkspaceLogicalRow(secondaryCompareRow, { additive: true })\", \"secondary compare selection\")
text = replace_once(text, \"await selectWorkspaceLogicalRow(primaryBulkRow)\", \"await selectWorkspaceLogicalRow(primaryBulkRow, { additive: false })\", \"primary bulk selection\")
text = replace_once(text, \"await selectWorkspaceLogicalRow(secondaryBulkRow)\", \"await selectWorkspaceLogicalRow(secondaryBulkRow, { additive: true })\", \"secondary bulk selection\")
text = replace_once(text, \"await selectWorkspaceLogicalRow(primaryLifecycleRow)\", \"await selectWorkspaceLogicalRow(primaryLifecycleRow, { additive: false })\", \"primary lifecycle selection\")
text = replace_once(
    text,
    \"\"\"    await clickResilientButton(page, 'Discard Changes')
    await expect(page.getByText('Assets Import')).not.toBeVisible()\"\"\",
    \"\"\"    const dirtyGuard = page.getByRole('alertdialog', { name: 'Unsaved Changes', exact: true })
    await expect(dirtyGuard).toBeVisible({ timeout: 15_000 })
    await expect(dirtyGuard).toHaveAccessibleDescription('You have unsaved changes. Close this window and discard them?')
    await dirtyGuard.getByRole('button', { name: 'Discard Changes', exact: true }).click()
    await expect(importDialog).not.toBeVisible()\"\"\",
    \"import dirty close guard\",
)
(target / p).write_text(text)

patch_parts = []
for p in files:
    before = (base / p).read_text().splitlines(keepends=True)
    after = (target / p).read_text().splitlines(keepends=True)
    diff = list(difflib.unified_diff(before, after, fromfile=f\"a/{p}\", tofile=f\"b/{p}\", n=3))
    if not diff:
        raise SystemExit(f\"no patch for {p}\")
    patch_parts.append(f\"diff --git a/{p} b/{p}\\n\" + \"\".join(diff))
patch = \"\".join(patch_parts)
patch_path = root / \"CHG-57-R19.patch\"
patch_path.write_text(patch)
print(\"PATCH_SHA256\", hashlib.sha256(patch.encode()).hexdigest())
print(\"PATCH_BYTES\", len(patch.encode()))
for p in files:
    print(\"BASE_SHA256\", p, hashlib.sha256((base / p).read_bytes()).hexdigest())
    print(\"POST_SHA256\", p, hashlib.sha256((target / p).read_bytes()).hexdigest())
print(\"PATCH_PATH\", patch_path)
print(patch)

PY"
